let a = tensor(0.1, requires_grad=true)
let x = tensor(2.0)
let y_target = tensor(4.0)
let lr = 0.04

let iter = 1
while iter <= 6:
    let y_pred = a * (x ** 2)
    let loss = (y_pred - y_target) ** 2
    loss.backward()
    let next_a = a.item() - lr * a.grad.item()
    a = tensor(next_a, requires_grad=true)
    iter += 1

print("Quadratic coefficient a:", a.item())
```

