let model = Sequential([
    Linear(2, 4),
    ReLU(),
    Linear(4, 1)
])

let optimizer = Adam(model.parameters(), lr=0.05)
let criterion = MSELoss()

let X = tensor([[1.0, 2.0], [2.0, 3.0], [3.0, 4.0]])
let Y = tensor([[3.0], [5.0], [7.0]])

let epoch = 1
while epoch <= 8:
    let y_pred = model(X)
    let loss = criterion(y_pred, Y)
    optimizer.zero_grad()
    loss.backward()
    optimizer.step()
    epoch += 1

print("Final loss:", loss.item())
```

