let w = tensor(0.11, requires_grad=true)
let x = tensor(2.0)
let y_target = tensor(10.0)
let lr = 0.05

let epoch = 1
while epoch <= 10:
    let pred = w * x
    let loss = (pred - y_target) ** 2
    loss.backward()
    let updated = w.item() - lr * w.grad.item()
    w = tensor(updated, requires_grad=true)
    epoch += 1

print("Optimized weight:", w.item())
```

